export const events = {
	appearanceCorners: (callback: (payload: Corners) => void) => listen<Corners>("appearance.corners", callback),
	appearanceLines: (callback: (payload: Lines) => void) => listen<Lines>("appearance.lines", callback),
	appearanceMotion: (callback: (payload: Motion) => void) => listen<Motion>("appearance.motion", callback),
	appearanceTypography: (callback: (payload: Typography) => void) => listen<Typography>("appearance.typography", callback),
	kestrelPalette: (callback: (payload: Palette) => void) => listen<Palette>("kestrel.palette", callback),
};

export type AltGr = "ralt" | "lalt" | "alt" | "rctrl" | "menu" | "rwin" | "caps";

export type AppIconStyle = "default" | "tinted" | "clear";

export type AppIcons = {
	style: AppIconStyle,
	glyphs: string,
	tinted: IconPaint,
	clear: IconPaint,
};

export type AppState = Appearance & Launch;

export type Appearance = {
	palette: Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	lines: Lines,
	locale: Locale,
};

export type CapsLock = "capslock" | "shiftlock" | "escape" | "swapescape" | "backspace" | "ctrl" | "none";

export type Character = {
	text: string,
	name: string,
};

export type ComposeKey = "none" | "ralt" | "rctrl" | "menu" | "rwin" | "caps" | "sclk" | "prsc";

export type Corners = "rounded" | "square";

export type DeadKey = {
	keysym: string,
	name: string,
	symbol: string,
	spacing: string,
	pairs: Pair[],
};

export type Entry = {
	keys: string,
	text: string,
};

export type ExportFormat = "symbols" | "keymap" | "compose" | "klc";

export type IconPaint = {
	plate: string,
	ink: string,
	shade: string,
	rim: number,
};

export type Kind = "empty" | "character" | "dead" | "compose" | "function";

export type Launch = {
	link: string | null,
	opened: Opened[],
	failed: string[],
};

export type Layout = {
	id: string,
	name: string,
	short: string,
	language: string,
	base: string | null,
	keys: { [key in string]: [Symbol, Symbol, Symbol, Symbol] },
	dead: DeadKey[],
	options: Options,
};

export type LayoutEntry = {
	id: string,
	name: string,
	short: string,
	language: string,
};

export type Lines = "none" | "lines" | "scanlines";

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Method = {
	name: string,
	label: string,
	language: string,
	candidates: number,
	learn: boolean,
	compose: string,
	rules: Rule[],
	words: Entry[],
	sequences: Entry[],
};

export type Motion = "full" | "reduced" | "off";

export type Opened = { kind: "layout"; id: string } | { kind: "method"; id: string };

export type Options = {
	altgr: AltGr,
	compose: ComposeKey,
	caps: CapsLock,
};

export type Origin = { kind: "system"; id: string } | { kind: "user"; id: string };

export type Pair = {
	base: string,
	text: string,
	next?: string,
};

export type Palette = {
	accent: string,
	wallpaperAccent: string,
	pureBlack: boolean,
	colors: SchemeColors,
	terminal: SchemeColors,
	appIcons: AppIcons,
	taskbar: import("@luft/ui").TaskbarLooks,
};

export type Rule = {
	keys: string,
	text: string,
	after?: string,
};

export type SavedMethod = {
	id: string,
} & Method;

export type SchemeColors = {
	light: { [key in string]: string },
	dark: { [key in string]: string },
};

export type Shown = {
	handled: boolean,
	commit: string,
	preedit: string,
	candidates: string[],
	selected: number,
	first: number,
	total: number,
};

export type Specials = {
	dead: Symbol[],
	compose: Symbol,
};

export type Summary = {
	id: string,
	name: string,
	label: string,
	language: string,
};

export type Symbol = {
	keysym: string,
	text: string,
	kind: Kind,
};

export type SystemTable = {
	spacing: string,
	pairs: Pair[],
};

export type Targets = {
	link: string | null,
	files: string[],
};

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};

export type Viewed = {
	custom: boolean,
} & Layout;
